#!/usr/bin/env bash
# Keep the Overleaf-linked paper repository and this repository's manuscript in step.
#
#   scripts/sync_overleaf.sh export PAPER_REPO_DIR   # this repo -> paper repo; then commit and push there and pull in Overleaf
#   scripts/sync_overleaf.sh import PAPER_REPO_DIR   # paper repo -> this repo; then re-checks every number in the manuscript
#
# The paper repository names the manuscript main.tex (Overleaf's main document); here it is paper/qai_paper.tex.
# Figures only travel outwards: they are generated by scripts/make_figures.py from the result files.
set -euo pipefail
mode=${1:?usage: sync_overleaf.sh export|import PAPER_REPO_DIR}
target=${2:?usage: sync_overleaf.sh export|import PAPER_REPO_DIR}
root=$(cd "$(dirname "$0")/.." && pwd)
[ -d "$target/.git" ] || { echo "$target is not a git clone of the paper repository" >&2; exit 1; }
case "$mode" in
  export)
    mkdir -p "$target/figures"
    cp "$root/paper/qai_paper.tex" "$target/main.tex"
    cp "$root/paper/references.bib" "$target/references.bib"
    cp "$root/paper/figures/fig_representation.pdf" "$root/paper/figures/fig_results.pdf" "$target/figures/"
    echo "exported manuscript, bibliography and two figures to $target"
    ;;
  import)
    cp "$target/main.tex" "$root/paper/qai_paper.tex"
    cp "$target/references.bib" "$root/paper/references.bib"
    echo "imported manuscript and bibliography; checking every number against the result files"
    python3 "$root/scripts/check_manuscript_numbers.py"
    ;;
  *) echo "unknown mode: $mode (use export or import)" >&2; exit 1 ;;
esac
